t = int(input())
while t:
	n = int(input())
	p = input().split()
	p = [int(x) for x in p]
	q = [0 for i in range(n)]
	for i in range(n):
		q[p[i] - 1] = i + 1
	flag = True
	prev = q[0]
	for i in range(1, n):
		if q[i] != prev + 1:
			if q[i] > prev:
				flag = False
				break
			prev = q[i]
		else:
			prev = q[i]
	if flag:
		print('Yes')
	else:
		print('No')
	t -= 1
